{
  "db": "ok",
  "redis": "ok",
  "status": "UP"
}
```

의존성 없이 동작하며, 하나라도 실패하면 HTTP 503 + `"status": "DOWN"` 반환.

```java
@RestController
@RequestMapping("/api")
public class HealthController {

    private final DataSource dataSource;
    private final StringRedisTemplate redisTemplate;

    public HealthController(DataSource dataSource, StringRedisTemplate redisTemplate) {
        this.dataSource = dataSource;
        this.redisTemplate = redisTemplate;
    }

    @GetMapping("/health")
    public Map<String, Object> health() {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("status", "UP");
        result.put("db", checkDb());
        result.put("redis", checkRedis());

        boolean allUp = "UP".equals(((Map<?, ?>) result.get("db")).get("status"))
                     && "UP".equals(((Map<?, ?>) result.get("redis")).get("status"));
        if (!allUp) result.put("status", "DOWN");
        return result;
    }

    private Map<String, String> checkDb() {
        try (Connection conn = dataSource.getConnection()) {
            conn.createStatement().execute("SELECT 1");
            return Map.of("status", "UP");
        } catch (Exception e) {
            return Map.of("status", "DOWN", "error", e.getMessage());
        }
    }

    private Map<String, String> checkRedis() {
        try {
            String pong = redisTemplate.getConnectionFactory().getConnection().ping();
            return Map.of("status", "UP", "ping", pong);
        } catch (Exception e) {
            return Map.of("status", "DOWN", "error", e.getMessage());
        }
    }
}
```

응답 예시:
```json
{
  "status": "UP",
  "db": { "status": "UP" },
  "redis": { "status": "UP", "ping": "PONG" }
}
```
